def expected_tokens(alpha, k):
    return (1 - alpha ** (k + 1)) / (1 - alpha)

for alpha in (0.6, 0.8, 0.9):
    print(alpha, [round(expected_tokens(alpha, k), 2) for k in (1, 3, 5)])
# 0.6 [1.6, 2.18, 2.38]
# 0.8 [1.8, 2.95, 3.69]
# 0.9 [1.9, 3.44, 4.69]

import math
def cos(u, v):
    return sum(x * y for x, y in zip(u, v)) / (math.hypot(*u) * math.hypot(*v))
image = [0.9, 0.1, 0.3]
labels = {"무선청소기": [0.8, 0.2, 0.4], "선풍기": [0.2, 0.9, 0.1], "전기포트": [0.1, 0.3, 0.9]}
for name, vec in sorted(labels.items(), key=lambda kv: -cos(image, kv[1])):
    print(name, round(cos(image, vec), 3))
# 무선청소기 0.984
# 전기포트 0.429
# 선풍기 0.339
